const body = $input.first().json.body || $input.first().json || {};
const numeroTrain = (body.numero_train || '').trim().toUpperCase();
const date = (body.date || new Date().toISOString().split('T')[0]).trim();
const operateur = (body.operateur || 'sncf').toLowerCase();
const threshold = parseInt(body.alert_threshold_minutes || 5, 10);
const callbackUrl = body.callback_url || 'http://127.0.0.1:8000/api/train/alert';
const userEmail = body.user_email || 'pierrecassagnettes@gmail.com';

return [{
  json: {
    numero_train: numeroTrain,
    date: date,
    operateur: operateur,
    alert_threshold_minutes: threshold,
    callback_url: callbackUrl,
    user_email: userEmail,
    status: 'monitoring_registered',
    registered_at: new Date().toISOString()
  }
}];

const prev = $node['Formater Paramètres Surveillance'].json;
let apiRes = {};
try {
  apiRes = $input.first().json;
} catch (e) {}

// Détection et calcul du retard (en minutes)
let delayMinutes = 0;
let isCancelled = false;
let track = 'Voie 2';
let deviations = [];

if (apiRes && apiRes.RESPONSE && apiRes.RESPONSE.RESULT && apiRes.RESPONSE.RESULT[0]?.TrainAnnouncement) {
  const announcements = apiRes.RESPONSE.RESULT[0].TrainAnnouncement;
  if (announcements.length > 0) {
    const a = announcements[0];
    isCancelled = a.Canceled === true || a.Canceled === 'true';
    track = a.TrackAtLocation || track;
    if (a.Deviation && Array.isArray(a.Deviation)) {
      deviations = a.Deviation.map(d => typeof d === 'string' ? d : d.Description || '');
    }
    if (a.AdvertisedTimeAtLocation && a.EstimatedTimeAtLocation) {
      const adv = new Date(a.AdvertisedTimeAtLocation).getTime();
      const est = new Date(a.EstimatedTimeAtLocation).getTime();
      delayMinutes = Math.max(0, Math.round((est - adv) / 60000));
    }
  }
} else {
  // Simulation / Fallback intelligent
  delayMinutes = 0;
}

const shouldAlert = isCancelled || delayMinutes >= prev.alert_threshold_minutes;
const alertMsg = isCancelled 
  ? `ALERTE PERTURBATION : Le train ${prev.numero_train} du ${prev.date} est annoncé ANNULÉ.`
  : `ATTENTION : Le train ${prev.numero_train} présente un retard de ${delayMinutes} minutes (Voie : ${track}).`;

return [{
  json: {
    numero_train: prev.numero_train,
    date: prev.date,
    operateur: prev.operateur,
    delay_minutes: delayMinutes,
    is_cancelled: isCancelled,
    track: track,
    deviations: deviations,
    should_alert: shouldAlert,
    alert_message: alertMsg,
    callback_url: prev.callback_url,
    user_email: prev.user_email,
    checked_at: new Date().toISOString()
  }
}];
